const {
  SystemMessage,
  HumanMessage,
  AIMessage,
} = require("@langchain/core/messages");
const { getChatModel } = require("../models/llm");

/**
 * 2. MESSAGE HANDLING
 *
 * Modern chat LLMs do not just take flat strings; they operate on structured messages
 * with distinct conversational roles.
 *
 * LangChain provides strongly-typed message classes:
 * - SystemMessage: Sets the persona, behavior, instructions, or guardrails for the model.
 * - HumanMessage: Represents the user's input/query.
 * - AIMessage: Represents the response generated by the language model.
 *
 * Flow:
 *   [ SystemMessage, HumanMessage ]
 *                 │
 *                 ▼
 *          LangChain Model
 *                 │
 *                 ▼
 *             AIMessage
 *
 * Note: We are explicitly NOT implementing conversation history/memory here.
 * This demonstrates the fundamental message structures that chat models consume and produce.
 */

/**
 * Sends a structured message array (SystemMessage + HumanMessage) to the model.
 *
 * @param {string} question - The user's input question
 * @returns {Promise<Object>} Object containing the message roles, contents, and the resulting AIMessage
 */
async function executeMessageFlow(question) {
  const model = getChatModel();

  // 1. SystemMessage: Define the AI persona and instructional boundaries
  const systemMessage = new SystemMessage(
    "You are a friendly and clear computer science educator. Explain concepts simply and accurately without unnecessary jargon."
  );

  // 2. HumanMessage: The prompt or query originating from the user
  const humanMessage = new HumanMessage(question);

  // 3. Model invocation: Model receives an array of messages
  const response = await model.invoke([systemMessage, humanMessage]);

  // 4. The model returns an AIMessage instance
  const isAIMessage = response instanceof AIMessage;

  return {
    systemRole: systemMessage.content,
    humanRole: humanMessage.content,
    aiResponse: response.content,
    messageTypes: {
      sent: ["SystemMessage", "HumanMessage"],
      received: isAIMessage ? "AIMessage" : response.constructor.name,
    },
  };
}

module.exports = {
  executeMessageFlow,
};
